text:
{
  "assessment": "The source provides a detailed theoretical and numerical framework for Floquet influence functionals applied to driven spin-boson models. The selected quantitative cluster focuses on the period-averaged asymptotic heat current density in the driven spin-boson model, with explicit formulas for the heat current and its asymptotic delta-peak contributions. The source reports specific parameter values (alpha=0.05, omega_c=2.5 Omega, epsilon_d=1 Omega) and driving frequencies, but does not provide explicit numeric values for the heat current density itself; the results are presented graphically. Therefore, while the mechanism and equations are well-defined, the lack of numeric readout values prevents full case authoring readiness.",
  "case_authoring_ready": false,
  "source": {
    "citation": "Konrad Mickiewicz, Exact Floquet Dynamics of Strongly Damped Driven Quantum Systems, Physical Review Letters (2026), DOI:10.1103/5z1m-122d",
    "journal_doi": "10.1103/5z1m-122d",
    "arxiv_versioned_id": "2511.08754v3"
  },
  "paper_scope": "The paper introduces a Floquet influence functional framework for simulating strongly damped driven quantum systems, applied to driven spin-boson models. It studies Floquet heating of the bath and driving-assisted entanglement stabilization in a two-spin-boson model. The selected cluster focuses on the heat current density in the single-qubit driven spin-boson model.",
  "mechanisms": [
    {
      "mechanism_id": "heat_current_density",
      "statement": "The period-averaged asymptotic heat current density in a driven spin-boson model is given by an integral over the period-averaged asymptotic correlation function, with delta-peak contributions from the factorized part.",
      "equations": [
        "j(t, omega) = 2 J(omega) omega int_0^t ds Im{ ((1+2 n_B(omega)) sin(omega (t-s)) + i cos(omega (t-s))) <S(t)S(s)> }",
        "overline{j}(omega) = 2 J(omega) omega int_0^infty dtau Im{ ((1+2 n_B(omega)) sin(omega tau) + i cos(omega tau)) overline{C}(tau) }",
        "overline{j}_{asym}(omega) = pi J(omega) omega sum_{n=0}^infty c_n delta(omega - omega_d n)"
      ],
      "variable_names": [
        "j(t, omega)",
        "overline{j}(omega)",
        "J(omega)",
        "omega",
        "n_B(omega)",
        "S(t)",
        "overline{C}(tau)",
        "c_n",
        "omega_d"
      ],
      "parameters": [
        {
          "name": "alpha_coupling",
          "value": 0.05,
          "uncertainty": "source_unspecified",
          "unit": "dimensionless",
          "role": "system-bath coupling strength in the Ohmic spectral density",
          "anchors": [
